const SHELL='adam-cooks-shell-'+CONFIG.build,INDEX='adam-cooks-download-index-v1',PREFIX='adam-cooks-recipe-',INDEX_URL=new URL('/__adam_cooks_downloads__',self.location.origin).href;
let writes=Promise.resolve();
function friendly(error){if(error.name==='QuotaExceededError')return 'There is not enough browser storage for this download. Remove another download or free some space, then try again.';if(error instanceof TypeError)return 'Connect to the internet to download or update this recipe.';return error.message||'Offline storage could not be updated.';}
const publicURL=value=>{const url=new URL(value,self.location.origin);if(url.origin!==self.location.origin||!/\.(?:html|css|js|json|webp|jpg|png|svg|webmanifest)$/.test(url.pathname))throw Error('That resource cannot be saved offline.');return url.href;};
async function registry(){const c=await caches.open(INDEX),r=await c.match(INDEX_URL);if(!r)return {};try{const data=await r.json();return data&&typeof data==='object'?data:{};}catch{return {};}}
