async function list(){const data=await registry(),result=[];for(const [file,item]of Object.entries(data)){if(!item||!item.cache?.startsWith(PREFIX)||!await caches.has(item.cache))continue;const c=await caches.open(item.cache);if((await c.keys()).length!==item.assets||!await c.match(publicURL(file)))continue;result.push({file,name:item.name,savedAt:item.savedAt,version:item.version});}return result.sort((a,b)=>b.savedAt-a.savedAt);}
async function save(file){if(typeof file!=='string')throw Error('Choose a recipe first.');const response=await fetch('/offline-catalog.json',{cache:'no-store',credentials:'omit'});if(!response.ok)throw Error('Connect to the internet to download or update a recipe.');const fresh=await response.json(),entry=fresh.recipes?.[file];if(!entry||!Array.isArray(entry.assets)||entry.assets.length>100||!Array.isArray(fresh.shell)||fresh.shell.length>100)throw Error('This recipe is not available to download.');
 const urls=[...new Set([...entry.assets,...fresh.shell].map(publicURL))],cacheName=PREFIX+Date.now()+'-'+Math.random().toString(36).slice(2),cache=await caches.open(cacheName);try{await fetchInto(cache,urls);const data=await registry(),old=data[file];data[file]={cache:cacheName,name:entry.name,savedAt:Date.now(),version:entry.version,assets:urls.length};await writeRegistry(data);if(old?.cache?.startsWith(PREFIX))await caches.delete(old.cache);return true;}catch(error){await caches.delete(cacheName);throw error;}}
